import { useCallback, useMemo } from 'react';

import { useCommercialSelectOptions } from 'components/Filter/hooks/useCommercialSelectOptions';
import { useQuickFilter } from 'components/Filter/hooks/useQuickFilter';
import { FieldProps } from 'components/Filter/types';
import {
  isFilterSelectClearableEnabledForPage,
  shouldShowFilterSelectClearIndicator,
} from 'components/Filter/utils/filterClearableSelectPolicy';
import { Select } from 'components/Form';
import { FilterRegistry } from 'domain/Filter';
import {
  type CommercialSkuDimension,
  type CommercialSkuOption,
  findSubBrandForSku,
  getCommercialSkuOptions,
  shouldAutoLinkSubBrandForSku,
} from 'domain/Filter/commercialResultsSkuHierarchy';
import { Option } from 'models/Filters';

export const CommercialFlatQuickFilter = ({
  dataTestId,
  fieldKey,
  pageName,
  onValueChange,
  getCurrentValue,
}: FieldProps) => {
  const countryValue = getCurrentValue('country');
  const zoneValue = getCurrentValue('zone');
  const brandValue = getCurrentValue('brands');
  const subBrandsValue = getCurrentValue('sub_brands');

  const filterContext = useMemo(() => {
    if (fieldKey === 'region') {
      return { country: countryValue };
    }
    if (fieldKey === 'sku') {
      return {
        zone: zoneValue,
        country: countryValue,
        brands: brandValue,
        sub_brands: subBrandsValue,
      };
    }
    return {};
  }, [fieldKey, countryValue, zoneValue, brandValue, subBrandsValue]);

  const valueLabel = useMemo(
    () =>
      FilterRegistry.getInstance().get(fieldKey)?.metadata?.displayName ??
      fieldKey,
    [fieldKey],
  );

  const {
    options: quickFilterOptions,
    currentValue,
    handleValueChange: baseHandleValueChange,
    handleClear,
    showClearIcon: defaultShowClearIcon,
    defaults,
    dataFilters,
  } = useQuickFilter({
    fieldKey,
    pageName,
    gaCategory: `${valueLabel} Select`,
    filterContext,
    onValueChange,
    getCurrentValue,
  });

  const {
    rawOptions,
    selectableOptions,
    isCommercialPage,
    commercialDisplayValue,
  } = useCommercialSelectOptions({
    pageName,
    rawOptions: quickFilterOptions,
    formValue: currentValue,
    defaultValue: defaults?.[fieldKey],
  });

  const displayValue = isCommercialPage
    ? (commercialDisplayValue ?? currentValue)
    : currentValue;

  const showClearIcon = isFilterSelectClearableEnabledForPage(pageName)
    ? shouldShowFilterSelectClearIndicator(
        pageName,
        fieldKey,
        String(currentValue ?? ''),
        rawOptions,
        defaults,
      )
    : defaultShowClearIcon;

  const disabled = fieldKey === 'sku' && selectableOptions.length === 0;

  const allBrandSkuOptions = useMemo((): CommercialSkuOption[] => {
    if (fieldKey !== 'sku' || !isCommercialPage) {
      return [];
    }
    return getCommercialSkuOptions(
      dataFilters?.sku as CommercialSkuDimension | undefined,
      brandValue,
    );
  }, [fieldKey, isCommercialPage, dataFilters?.sku, brandValue]);

  const handleValueChange = useCallback(
    (option: Option) => {
      if (fieldKey === 'sku' && isCommercialPage && option?.value) {
        const linkedSubBrand = findSubBrandForSku(
          allBrandSkuOptions,
          option.value,
        );
        if (shouldAutoLinkSubBrandForSku(subBrandsValue, linkedSubBrand)) {
          onValueChange('sub_brands', {
            value: linkedSubBrand,
            label: linkedSubBrand,
          });
        }
      }
      baseHandleValueChange(option);
    },
    [
      allBrandSkuOptions,
      baseHandleValueChange,
      fieldKey,
      isCommercialPage,
      onValueChange,
      subBrandsValue,
    ],
  );

  return (
    <Select
      dataTestId={dataTestId ? `${dataTestId}-${fieldKey}` : undefined}
      id={`${fieldKey}-select-quick-filter`}
      value={displayValue}
      options={selectableOptions}
      disabled={disabled}
      onValueChange={(option) => {
        const opt = Array.isArray(option) ? option[0] : option;
        handleValueChange(opt as Option);
      }}
      size="medium"
      shape="pill"
      placeholder={`Select ${valueLabel}`}
      chips
      clearChips={showClearIcon}
      onClearSingle={handleClear}
      valueLabel={valueLabel}
      searchable={selectableOptions.length > 6}
    />
  );
};
